const FASE_ACTUAL = 3;

const identidadFases = [
  { nombre:"PREPARACIÓN", subtitulo:"Paz aparente - reúne recursos", amenaza:"BAJA", pct:12 },
  { nombre:"EL DESPERTAR", subtitulo:"Nether abierto - primeras mutaciones", amenaza:"MODERADA", pct:30 },
  { nombre:"SUPERVIVENCIA", subtitulo:"End desbloqueado - Doom sellado hasta Fase 3", amenaza:"ALTA", pct:48 },
  { nombre:"PESADILLA", subtitulo:"Doom desbloqueado - comienzan las expediciones", amenaza:"SEVERA", pct:66 },
  { nombre:"MUERTE INMINENTE", subtitulo:"Élites, tormentas y errores letales", amenaza:"CRÍTICA", pct:84 },
  { nombre:"APOCALIPSIS TOTAL", subtitulo:"El Evento ha dejado de perdonar", amenaza:"EXTREMA", pct:100 }
];

function obtenerFaseActual(){ return Math.max(0, Math.min(5, Number(FASE_ACTUAL)||0)); }

function aplicarIdentidadDeFase(){
  const fase=obtenerFaseActual(), data=identidadFases[fase];
  document.body.dataset.phase=String(fase);

  const setText=(id,val)=>{ const el=document.getElementById(id); if(el) el.textContent=val; };
  setText("page-phase-name", `FASE ${fase} - ${data.nombre}`);
  setText("page-phase-sub", data.subtitulo);
  setText("page-threat-label", data.amenaza);
  setText("phase-status-title", `FASE ${fase} - ${data.nombre}`);
  setText("phase-status-sub", data.subtitulo);
  setText("intro-phase-name", `FASE ${fase} - ${data.nombre}`);
  setText("intro-phase-sub", data.subtitulo);
  setText("intro-threat-label", data.amenaza);
  setText("phase-current-number", String(fase));
  setText("threat-label", data.amenaza);

  ["page-threat-fill","threat-fill","intro-threat-fill"].forEach(id=>{
    const el=document.getElementById(id); if(el) el.style.width=`${data.pct}%`;
  });

  document.querySelectorAll("[data-node-phase]").forEach(node=>{
    const p=Number(node.dataset.nodePhase);
    node.classList.toggle("is-complete",p<fase);
    node.classList.toggle("is-current",p===fase);
    node.classList.toggle("is-locked",p>fase);
  });

  document.querySelectorAll("#evolucion-fases .phase-box[data-phase]").forEach(box=>{
    box.classList.toggle("phase-active",Number(box.dataset.phase)===fase);
  });

  document.querySelectorAll(".phase-item-group .phase-now").forEach(b=>b.remove());
  const head=document.querySelector(`.phase-item-group[data-phase-group="${fase}"] .phase-group-header`);
  if(head){
    const badge=document.createElement("span");
    badge.className="phase-now"; badge.textContent="ACTUAL"; head.appendChild(badge);
  }
}

function aplicarBloqueoDeFases(){
  const permitida=obtenerFaseActual();
  document.querySelectorAll("[data-unlock-phase]").forEach(el=>{
    const fase=Number(el.dataset.unlockPhase);
    if(!Number.isFinite(fase)||fase<=permitida) return;

    if(el.classList.contains("phase-item-group")){
      el.classList.add("phase-item-group-locked");
      const grid=el.querySelector(".grid");
      if(grid) grid.innerHTML=`<div class="card phase-gated-card"><span class="phase-gated-code">FASE ${fase}</span><h3>------</h3></div>`;
      return;
    }
    if(el.classList.contains("phase-section")){
      el.classList.add("phase-section-locked");
      el.innerHTML=`<h2 class="section-title">FASE ${fase}</h2><div class="phase-box phase-locked"><h4>------</h4></div>`;
      return;
    }
    if(el.classList.contains("phase-box")){
      el.classList.add("phase-locked");
      el.innerHTML=`<h4>FASE ${fase} - ------</h4>`;
      return;
    }
    el.innerHTML="";
    el.hidden=true;
  });
}

// ---------- RECETAS ----------
function cargarIconosReceta(entry){
  if(!entry) return;
  entry.querySelectorAll("img[data-src]").forEach(img=>{
    if(img.dataset.loaded==="1") return;
    img.src=img.dataset.src;
    img.dataset.loaded="1";
    img.addEventListener("error",()=>{
      img.classList.add("recipe-icon-missing");
      img.removeAttribute("src");
    },{once:true});
  });
}

function iniciarRecetas(){
  const entries=[...document.querySelectorAll(".recipe-entry")];
  const cerrar=(excepto=null)=>entries.forEach(entry=>{
    if(entry===excepto) return;
    entry.classList.remove("is-open");
    entry.querySelector(".recipe-toggle")?.setAttribute("aria-expanded","false");
  });
  entries.forEach(entry=>{
    const btn=entry.querySelector(".recipe-toggle");
    if(!btn) return;

    // Desktop hover/focus loads icons just before the popover becomes useful.
    entry.addEventListener("mouseenter",()=>cargarIconosReceta(entry),{passive:true});
    entry.addEventListener("focusin",()=>cargarIconosReceta(entry));

    btn.addEventListener("click",e=>{
      e.preventDefault();
      cargarIconosReceta(entry);
      const abrir=!entry.classList.contains("is-open");
      cerrar(entry); entry.classList.toggle("is-open",abrir);
      btn.setAttribute("aria-expanded",abrir?"true":"false");
    });
    btn.addEventListener("keydown",e=>{
      if(e.key==="Escape"){ entry.classList.remove("is-open"); btn.setAttribute("aria-expanded","false"); btn.blur(); }
    });
  });
  document.addEventListener("click",e=>{ if(!e.target.closest(".recipe-entry")) cerrar(); });
}

