const rarityData={
  gold:{label:"Dorada",color:"#ffe15b",marker:"§k§e§r",visible:"§e"},
  orange:{label:"Naranja",color:"#ff9d32",marker:"§k§6§r",visible:"§6"},
  red:{label:"Roja",color:"#ff4d57",marker:"§k§4§r",visible:"§4"},
  violet:{label:"Violeta",color:"#c45cff",marker:"§k§5§r",visible:"§5"},
  green:{label:"Verde",color:"#56f09d",marker:"§k§a§r",visible:"§a"},
  cyan:{label:"Cian",color:"#4ce7f2",marker:"§k§b§r",visible:"§b"},
  teal:{label:"Turquesa",color:"#35c9bd",marker:"§k§3§r",visible:"§3"},
  white:{label:"Blanca",color:"#f1f1f1",marker:"§k§f§r",visible:"§f"}
};
let selectedRarity="violet";

function actualizarForja(){
  const input=document.getElementById("rarity-name");
  const output=document.getElementById("rarity-output");
  const preview=document.getElementById("rarity-preview");
  const previewName=document.getElementById("rarity-preview-name");
  const previewColor=document.getElementById("rarity-preview-color");
  const bold=document.getElementById("rarity-bold");
  if(!input||!output||!preview||!previewName||!previewColor||!bold) return;

  const data=rarityData[selectedRarity];
  const name=(input.value||"Mi arma").replace(/[\r\n]/g," ").trim().slice(0,40)||"Mi arma";
  output.value=`${data.marker}${data.visible}${bold.checked?"§l":""}${name}§r`;
  preview.style.setProperty("--rarity-color",data.color);
  preview.dataset.rarity=selectedRarity;
  document.querySelector(".rarity-builder")?.style.setProperty("--rarity-color",data.color);
  previewName.textContent=name;
  previewName.style.fontWeight=bold.checked?"900":"700";
  previewColor.textContent=`Estela ${data.label.toLowerCase()}`;

  document.querySelectorAll(".rarity-swatch").forEach(btn=>{
    const active=btn.dataset.rarity===selectedRarity;
    btn.classList.toggle("is-selected",active);
    btn.setAttribute("aria-checked",active?"true":"false");
  });
}

function iniciarForja(){
  document.querySelectorAll(".rarity-swatch").forEach(btn=>btn.addEventListener("click",()=>{
    selectedRarity=btn.dataset.rarity; actualizarForja();
  }));
  document.getElementById("rarity-name")?.addEventListener("input",actualizarForja);
  document.getElementById("rarity-bold")?.addEventListener("change",actualizarForja);
  document.getElementById("copy-rarity")?.addEventListener("click",async()=>{
    const output=document.getElementById("rarity-output");
    const status=document.getElementById("copy-rarity-status");
    if(!output||!status) return;
    try{
      await navigator.clipboard.writeText(output.value);
      status.textContent="Copiado. Pégalo directamente en el yunque.";
    }catch{
      output.focus(); output.select();
      try{ document.execCommand("copy"); status.textContent="Copiado. Pégalo directamente en el yunque."; }
      catch{ status.textContent="Selecciona el texto y cópialo manualmente."; }
    }
  });
  actualizarForja();
}

