// ---------- NAVEGACIÓN / INTERACCIÓN ----------
function iniciarNavegacion(){
  const btn=document.getElementById("site-menu-btn"), links=document.getElementById("site-nav-links");
  btn?.addEventListener("click",()=>links?.classList.toggle("open"));
  document.addEventListener("click",e=>{
    if(!e.target.closest(".site-topbar")) links?.classList.remove("open");
  });
  const back=document.getElementById("back-top");
  const sync=()=>back?.classList.toggle("is-visible",window.scrollY>650);
  window.addEventListener("scroll",sync,{passive:true}); sync();
  back?.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"}));
}

function iniciarInmersion(){
  // Performance: no pointermove/tilt calculations per card.
  document.querySelectorAll(".card,.hub-card").forEach(card=>{
    if(card.classList.contains("performance-lite")) return;
    card.addEventListener("pointerdown",e=>{
      if(e.target.closest("button,a,input,textarea,.recipe-entry")) return;
      const r=card.getBoundingClientRect();
      const ripple=document.createElement("span");
      ripple.className="sr-ripple";
      ripple.style.left=`${e.clientX-r.left}px`;
      ripple.style.top=`${e.clientY-r.top}px`;
      card.appendChild(ripple);
      setTimeout(()=>ripple.remove(),520);
    });
  });

  if("IntersectionObserver" in window && !matchMedia("(prefers-reduced-motion: reduce)").matches){
    const obs=new IntersectionObserver(entries=>entries.forEach(entry=>{
      if(entry.isIntersecting){ entry.target.classList.add("is-revealed"); obs.unobserve(entry.target); }
    }),{threshold:.05,rootMargin:"0px 0px -5% 0px"});
    document.querySelectorAll(".card:not(.performance-lite)").forEach(card=>{
      card.classList.add("reveal-ready");
      card.style.transitionDelay="0ms";
      obs.observe(card);
    });
  }
}

function iniciarAmbiente(){
  // Reading progress: one cheap width update per animation frame.
  const progress=document.createElement("div");
  progress.className="site-scroll-progress";
  progress.innerHTML="<i></i>";
  document.body.appendChild(progress);
  const fill=progress.firstElementChild;
  let ticking=false;
  const sync=()=>{
    const max=Math.max(1,document.documentElement.scrollHeight-window.innerHeight);
    fill.style.width=`${Math.min(100,(window.scrollY/max)*100)}%`;
    ticking=false;
  };
  window.addEventListener("scroll",()=>{
    if(!ticking){ requestAnimationFrame(sync); ticking=true; }
  },{passive:true});
  sync();

  if(!matchMedia("(prefers-reduced-motion: reduce)").matches){
    const field=document.createElement("div");
    field.className="ambient-motes";
    field.setAttribute("aria-hidden","true");
    const count=matchMedia("(max-width:900px)").matches?3:5;
    for(let i=0;i<count;i++){
      const mote=document.createElement("i");
      mote.className="ambient-mote";
      mote.style.left=`${7+(i*83)%91}%`;
      mote.style.setProperty("--mote-size",`${2+(i%3)}px`);
      mote.style.setProperty("--mote-duration",`${10+(i%5)*2.3}s`);
      mote.style.setProperty("--mote-delay",`${-((i*1.7)%11)}s`);
      mote.style.setProperty("--mote-drift",`${-28+(i%6)*12}px`);
      field.appendChild(mote);
    }
    document.body.prepend(field);
  }

  // Current tab inside a page responds to scroll.
  const tabLinks=[...document.querySelectorAll('.page-tabs a[href^="#"]')];
  const targets=tabLinks.map(a=>document.querySelector(a.getAttribute("href"))).filter(Boolean);
  if("IntersectionObserver" in window && targets.length){
    const tabObs=new IntersectionObserver(entries=>{
      const best=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];
      if(!best) return;
      tabLinks.forEach(a=>a.classList.toggle("active",a.getAttribute("href")===`#${best.target.id}`));
    },{threshold:[.08,.18,.34],rootMargin:"-18% 0px -58% 0px"});
    targets.forEach(t=>tabObs.observe(t));
  }
}



