function srSetActiveNav(url){
  const pathname=new URL(url,location.href).pathname;
  const file=pathname.split("/").pop()||"index.html";

  document.querySelectorAll(".site-nav-links a,.mobile-dock a").forEach(a=>{
    const href=(a.getAttribute("href")||"").split("#")[0];
    a.classList.toggle("active",href===file);
  });

  document.body.className=document.body.className
    .split(/\s+/)
    .filter(c=>!c.startsWith("page-"))
    .join(" ");

  const pageMap={
    "index.html":"home",
    "supervivencia.html":"survival",
    "arsenal.html":"arsenal",
    "enemigos.html":"threats",
    "personalizacion.html":"rarity",
    "doom.html":"doom",
    "fases.html":"phases",
    "eventos.html":"events"
  };
  if(pageMap[file]) document.body.classList.add(`page-${pageMap[file]}`);
}

async function srSpaNavigate(href,{push=true}={}){
  if(srSpaBusy) return;
  const url=new URL(href,location.href);

  // Anchor de la misma vista: no cambia documento.
  if(url.pathname===location.pathname && url.hash){
    document.querySelector(url.hash)?.scrollIntoView({behavior:"smooth",block:"start"});
    if(push) history.pushState({sr:true},"",url.href);
    return;
  }

  const file=url.pathname.split("/").pop()||"index.html";
  const cached=SR_EMBEDDED_PAGES[file];

  srSpaBusy=true;
  document.documentElement.classList.add("sr-spa-switching");

  const currentMain=document.querySelector(".site-main");
  const curtain=document.querySelector(".sr-nav-curtain");
  curtain?.classList.add("active");
  currentMain?.classList.add("sr-page-out");
  srLocalPlay("transition");

  try{
    await new Promise(r=>setTimeout(r,205));

    let nextMain=null;
    let nextTitle="";

    // PRIMERA OPCIÓN: caché incluida en app.js.
    // Funciona en hosting y también con file://, sin recargar el documento.
    if(cached){
      const tpl=document.createElement("template");
      tpl.innerHTML=cached.main.trim();
      nextMain=tpl.content.querySelector(".site-main");
      nextTitle=cached.title;
    }

    // Fallback de red si alguna página futura no está en la caché.
    if(!nextMain){
      const response=await fetch(url.href,{cache:"no-store"});
      if(!response.ok) throw new Error(`HTTP ${response.status}`);
      const text=await response.text();
      const parsed=new DOMParser().parseFromString(text,"text/html");
      nextMain=parsed.querySelector(".site-main");
      nextTitle=parsed.title||"";
    }

    if(!nextMain) throw new Error("No se encontró .site-main");

    // Solo cambia MAIN. Header, audio, navegación y reproductor nunca mueren.
    currentMain.replaceWith(nextMain);
    if(nextTitle) document.title=nextTitle;

    if(push) history.pushState({sr:true},"",url.href);
    srSetActiveNav(url.href);

    nextMain.classList.add("sr-page-in");
    window.scrollTo({top:0,behavior:"auto"});
    srInitPageContentV2();

    // Asegura que la intro jamás reaparezca al volver a Inicio por SPA.
    document.documentElement.classList.add("sr-intro-seen","sr-intro-complete");
    try{ sessionStorage.setItem("sr-intro-seen","1"); }catch{}

    setTimeout(()=>nextMain.classList.remove("sr-page-in"),520);
  }catch(err){
    // Último recurso. Las páginas internas no contienen intro, por lo que
    // incluso una recarga completa no repetirá la cinemática.
    try{ sessionStorage.setItem("sr-intro-seen","1"); }catch{}
    location.href=url.href;
    return;
  }finally{
    setTimeout(()=>curtain?.classList.remove("active"),320);
    document.documentElement.classList.remove("sr-spa-switching");
    srSpaBusy=false;
  }
}

function srInstallSpaNavigation(){
  const curtain=document.createElement("div");
  curtain.className="sr-nav-curtain";
  curtain.setAttribute("aria-hidden","true");
  document.body.appendChild(curtain);

  document.addEventListener("click",e=>{
    const a=e.target.closest('a[href]');
    if(!a) return;
    if(a.target==="_blank"||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey) return;

    const raw=a.getAttribute("href");
    if(!raw||raw.startsWith("http:")||raw.startsWith("https:")||raw.startsWith("mailto:")) return;

    const url=new URL(raw,location.href);
    const sameOrigin=url.origin===location.origin;
    const isHtml=/\.html$/i.test(url.pathname)||url.pathname.endsWith("/");
    if(!sameOrigin||!isHtml) return;

    // Las guías de jefes cargan su propio archivo de datos y su renderizador.
    // Se abren como documento completo para que sus patrones se construyan correctamente.
    const targetFile=url.pathname.split("/").pop()||"";
    const currentFile=location.pathname.split("/").pop()||"";
    if(/^boss-.*\.html$/i.test(targetFile)||/^boss-.*\.html$/i.test(currentFile)) return;

    e.preventDefault();
    srSpaNavigate(url.href,{push:true});
  },true);

  window.addEventListener("popstate",()=>{
    srSpaNavigate(location.href,{push:false});
  });
}

// Dynamic sounds delegated, so they also work after SPA swaps.
function srInstallDelegatedSounds(){
  let lastHover=0;

  document.addEventListener("mouseover",e=>{
    const target=e.target.closest(".site-nav-links a,.page-tabs a,.hub-card,.hero-btn");
    if(!target) return;
    if(target.contains(e.relatedTarget)) return;
    const now=performance.now();
    if(now-lastHover<145) return;
    lastHover=now;

    if(!srAudioAllowed) return;
    const a=srPersistentAudio.section;
    try{
      a.pause();
      a.currentTime=0;
      a.volume=.018;
      a.play().catch(()=>{});
      setTimeout(()=>{ a.volume=.065; },120);
    }catch{}
  });

  document.addEventListener("click",e=>{
    if(e.target.closest(".recipe-toggle")){
      srLocalPlay("recipe");
      return;
    }
    if(e.target.closest("#copy-rarity,.copy-rarity-btn")){
      srLocalPlay("copy");
      return;
    }
    if(e.target.closest(".site-menu-btn")){
      srLocalPlay("press");
      return;
    }
    if(e.target.closest(".page-tabs a")){
      srLocalPlay("section");
    }
  });
}




function srRestoreLocalAmbientAfterReload(){
  let active=false;
  try{ active=sessionStorage.getItem("sr-local-ambient-active")==="1"; }catch{}
  if(!active||!srAudioAllowed) return;

  try{
    const saved=Number(sessionStorage.getItem("sr-local-ambient-time")||0);
    if(Number.isFinite(saved)&&saved>0){
      srPersistentAudio.ambient.currentTime=saved;
    }
  }catch{}

  srTryStartAmbient();
}

function srPersistLocalAmbient(){
  try{
    if(srAmbientStarted&&!srPersistentAudio.ambient.paused){
      sessionStorage.setItem("sr-local-ambient-active","1");
      sessionStorage.setItem("sr-local-ambient-time",String(srPersistentAudio.ambient.currentTime||0));
    }
  }catch{}
}

window.addEventListener("pagehide",srPersistLocalAmbient);
setInterval(srPersistLocalAmbient,2500);


