function srBurstSectionSparks(section){
  if(!section||matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  if(section.querySelector(".sr-section-sparks")) return;

  const fx=document.createElement("div");
  fx.className="sr-section-sparks";
  fx.setAttribute("aria-hidden","true");

  for(let i=0;i<8;i++){
    const spark=document.createElement("i");
    spark.className="sr-section-spark";
    spark.style.left=`${7+(i*13)%86}%`;
    spark.style.top=`${8+(i%3)*8}%`;
    spark.style.setProperty("--sx",`${-16+(i%5)*8}px`);
    spark.style.setProperty("--sy",`${-20-(i%4)*10}px`);
    spark.style.animationDelay=`${i*35}ms`;
    fx.appendChild(spark);
  }

  section.appendChild(fx);
  setTimeout(()=>fx.remove(),1000);
}

function srInitSectionAtmosphere(){
  if(!("IntersectionObserver" in window)) return;
  const obs=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting) entry.target.classList.add("section-live");
    });
  },{threshold:.20,rootMargin:"-8% 0px -42% 0px"});
  document.querySelectorAll(".content-stack > section").forEach(section=>obs.observe(section));
}



function srCreatePhaseBackdrop(){
  const old=document.querySelector(".sr-phase-backdrop");
  if(old) old.remove();

  const fase=obtenerFaseActual();
  const data=identidadFases[fase];

  const bg=document.createElement("div");
  bg.className="sr-phase-backdrop";
  bg.setAttribute("aria-hidden","true");

  const watermark=document.createElement("div");
  watermark.className="sr-phase-watermark";
  watermark.innerHTML=`<span>0${fase}</span><b>${data.nombre}</b>`;
  bg.appendChild(watermark);

  const orbit1=document.createElement("i");
  orbit1.className="sr-phase-orbit one";
  const orbit2=document.createElement("i");
  orbit2.className="sr-phase-orbit two";
  bg.append(orbit1,orbit2);

  const geometry=document.createElement("div");
  geometry.className="sr-phase-geometry";
  for(let i=0;i<8;i++){
    const line=document.createElement("i");
    line.style.left=`${8+(i*13)%88}%`;
    line.style.top=`${5+(i*19)%82}%`;
    line.style.setProperty("--geo-r",`${-38+(i%6)*15}deg`);
    line.style.setProperty("--geo-speed",`${12+(i%5)*2.8}s`);
    line.style.setProperty("--geo-x",`${-22+(i%6)*9}px`);
    geometry.appendChild(line);
  }
  bg.appendChild(geometry);

  document.body.prepend(bg);

  const deepOld=document.querySelector(".sr-deep-bg");
  if(deepOld) deepOld.remove();

  const deep=document.createElement("div");
  deep.className="sr-deep-bg";
  deep.setAttribute("aria-hidden","true");
  deep.innerHTML=`
    <div class="sr-bg-nebula"></div>
    <div class="sr-bg-grid"></div>
    <div class="sr-bg-stars"></div>
    <div class="sr-bg-sigils"></div>
    <div class="sr-bg-hazards"></div>
    <div class="sr-bg-flares"></div>
  `;

  const stars=deep.querySelector(".sr-bg-stars");
  const starCount=matchMedia("(max-width:900px)").matches?6:10;
  for(let i=0;i<starCount;i++){
    const star=document.createElement("i");
    star.style.left=`${4+(i*17)%93}%`;
    star.style.top=`${5+(i*23)%88}%`;
    star.style.setProperty("--star-size",`${1+(i%3)}px`);
    star.style.setProperty("--star-speed",`${3.8+(i%5)*1.1}s`);
    star.style.setProperty("--star-delay",`${-((i*0.7)%5)}s`);
    star.style.setProperty("--star-rgb", i%2===0 ? "var(--phase-accent-rgb)" : "var(--phase-complement-rgb)");
    stars.appendChild(star);
  }

  const sigils=deep.querySelector(".sr-bg-sigils");
  const sigilData=[
    {left:"-9vw", top:"8vh", size:"min(28vw,360px)", speed:"29s"},
    {right:"-11vw", top:"54vh", size:"min(22vw,300px)", speed:"37s"},
    {left:"36vw", top:"68vh", size:"min(14vw,180px)", speed:"24s"}
  ];
  sigilData.forEach((cfg,idx)=>{
    const s=document.createElement("i");
    Object.entries(cfg).forEach(([k,v])=>{ if(k!=="size"&&k!=="speed") s.style[k]=v; });
    s.style.width=cfg.size;
    s.style.aspectRatio="1";
    s.style.setProperty("--sigil-speed", cfg.speed);
    s.style.opacity= idx===2 ? ".26" : ".38";
    if(idx===1) s.style.animationDirection="reverse";
    sigils.appendChild(s);
  });

  const hazards=deep.querySelector(".sr-bg-hazards");
  const hazardCount=matchMedia("(max-width:900px)").matches?3:5;
  for(let i=0;i<hazardCount;i++){
    const h=document.createElement("i");
    h.style.left=`${-4+(i*9)%96}%`;
    h.style.top=`${9+(i*7)%82}%`;
    h.style.setProperty("--hz-rot",`${-34+(i%7)*11}deg`);
    h.style.setProperty("--hz-speed",`${12+(i%5)*2.2}s`);
    h.style.setProperty("--hz-x",`${-26+(i%6)*10}px`);
    h.style.setProperty("--hz-y",`${12+(i%4)*11}px`);
    hazards.appendChild(h);
  }

  document.body.prepend(deep);
}



function srPlayRarity(level, burst=false){
  if(!srAudioAllowed) return;
  const map={"1":"rarity1","2":"rarity2","3":"rarity3","4":"rarity4","5":"rarity5"};
  const key=map[String(level)] || "rarity1";

  // A loot reveal should read as one event, not a pile of overlapping sounds.
  ["rarity1","rarity2","rarity3","rarity4","rarity5","legend"].forEach(name=>{
    const a=srPersistentAudio[name];
    if(!a) return;
    try{ a.pause(); a.currentTime=0; }catch{}
  });

  srLocalPlay(key);
  if(burst && String(level)==="5"){
    setTimeout(()=>srLocalPlay("legend"), 115);
  }
}


function srInitRarityFX(){
  let lastHover=0;
  let currentCard=null;

  document.querySelectorAll('.card[data-rarity][data-rarity-level]').forEach(card=>{
    card.style.setProperty('--mx','50%');
    card.style.setProperty('--my','46%');

    card.addEventListener('mouseenter', ()=>{
      if(currentCard===card) return;
      currentCard=card;

      const now=performance.now();
      if(now-lastHover<260) return;
      lastHover=now;

      srPlayRarity(card.dataset.rarityLevel, false);
    }, {passive:true});

    card.addEventListener('mouseleave', ()=>{
      if(currentCard===card) currentCard=null;
    }, {passive:true});

    card.addEventListener('click', ()=>{
      if(card.dataset.rarityLevel==="5"){
        srPlayRarity("5", true);
      }
    });
  });
}


